/**
 * `pasco export ai-policy [--out <dir> | --check]` — the M9 stance as an
 * artifact (SPEC §7.3, issue #290).
 *
 * The §12 M9 floor (published surfaces block AI-training crawlers by default)
 * had no artifact, and the other half — allowing the retrieval/answer crawlers,
 * which is what makes a profile citable — was nowhere expressed either. This
 * command ships both as three generated files plus the stated position:
 *
 *   robots.txt    two named groups: `ai-retrieval` allowed, `ai-training` blocked.
 *                 No bare `User-agent: *` allow-all is ever emitted: a wildcard
 *                 group would contradict the training block.
 *   llms.txt      the workspace index (name · definition · canonical identity ·
 *                 faq[] · publications[]) with a COVERAGE ASSERTION: every
 *                 document the builder claims to index must appear in the text.
 *   AI-POLICY.md  the human-readable statement: allowed, blocked, who can change
 *                 it, the date — quoting `ai.policy.stance` verbatim.
 *
 * **The policy is DERIVED DATA, never a committed workspace artifact.** A
 * committed robots.txt rots silently; a generator with a staleness gate turns rot
 * into a failing command (the §19.3 CHECKLIST.md precedent, and the generated
 * site root of #279). The crawler classification itself lives in
 * `platforms/registry.yaml` (`ai:`) and reaches this module through
 * `@profile-as-code/core` — the CLI never keeps a UA list of its own, and
 * `pnpm gen:platforms` refuses an entry with no source.
 *
 * `--check` loads no workspace: the UA list is registry data, which is what makes
 * the gate runnable in CI. It is the engine's declared clock-reading path (the
 * 180-day window), alongside `status --verify` (§19.5); the WRITE path reads no
 * clock at all — its dated stamp is `ai.policy.as_of`, so two runs at different
 * times produce byte-identical files (D19).
 *
 * Exit: 0 ok · 1 a --check problem, a schema/load failure (D12) or a write
 * failure · 2 usage (dispatcher).
 */

import {
  existsSync,
  mkdirSync,
  readFileSync,
  renameSync,
  unlinkSync,
  writeFileSync,
} from "node:fs";
import { join, resolve } from "node:path";
import type { AiCrawler, AiCrawlerFamily, Lang, LoadedProfile } from "@profile-as-code/core";
import {
  AI_CRAWLERS,
  AI_POLICY_AS_OF,
  AI_POLICY_STANCE,
  AI_POLICY_VERSION,
  entityId,
  LoadError,
  load,
  SchemaValidationError,
} from "@profile-as-code/core";
import { EXIT } from "../exit.js";
import { isJsonMode, line, report, section } from "../output.js";
import type { Pascorc } from "../workspace.js";

/** The frozen contract version of the `--json` payload (SPEC §7.3). */
export const AI_POLICY_SCHEMA_VERSION = "1";

/** A source older than this fails `--check`: a classification with no review in
 *  half a year is a claim nobody has re-verified. Declared, never tuned silently. */
export const AI_POLICY_MAX_AGE_DAYS = 180;

/** The three artifacts, in the order they are written. */
export const AI_POLICY_FILES = ["robots.txt", "llms.txt", "AI-POLICY.md"] as const;
export type AiPolicyFile = (typeof AI_POLICY_FILES)[number];

/**
 * Marker every generated file carries. It is how `--out` tells its OWN artifact
 * (safe to regenerate) from a file the user wrote (never truncated without
 * `--force`): a typo in `--out` must not eat a site's robots.txt.
 */
export const AI_POLICY_MARKER = "Generated by pasco export ai-policy";

export type AiPolicyProblemKind =
  | "unsourced"
  | "stale"
  | "future-dated"
  | "unknown-family"
  | "duplicate-ua"
  | "empty-group";

export interface AiPolicyProblem {
  kind: AiPolicyProblemKind;
  /** The registry slug the problem is about (a family name for `empty-group`). */
  entry: string;
  detail: string;
}

/** A crawler row as reported: the registry evidence plus the measured age. */
export interface AiCrawlerReport {
  slug: string;
  ua: string;
  operator: string;
  source: string;
  asOf: string;
  ageDays: number;
}

export interface AiPolicyData {
  schemaVersion: typeof AI_POLICY_SCHEMA_VERSION;
  policy: {
    version: number;
    asOf: string;
    stance: string;
    maxAgeDays: number;
  };
  groups: Record<AiCrawlerFamily, AiCrawlerReport[]>;
  problems: AiPolicyProblem[];
  /** Present only under `--out` (SPEC §7.3). */
  files?: { name: string; path: string; bytes: number }[];
}

const DAY_MS = 86_400_000;

/** Whole days between an ISO date and `now` (UTC dates, never local time). */
export function ageInDays(asOf: string, now: Date): number {
  const then = Date.parse(`${asOf}T00:00:00Z`);
  const today = Date.UTC(now.getUTCFullYear(), now.getUTCMonth(), now.getUTCDate());
  return Math.floor((today - then) / DAY_MS);
}

/**
 * The `--check` rules, pure and total: every problem class the command claims to
 * close has a branch here, and the write path runs the same function, so a stale
 * or unsourced list can never reach a file.
 */
export function checkCrawlers(
  crawlers: readonly AiCrawler[],
  now: Date,
  maxAgeDays: number = AI_POLICY_MAX_AGE_DAYS,
): AiPolicyProblem[] {
  const problems: AiPolicyProblem[] = [];
  const byUa = new Map<string, string>();

  for (const crawler of crawlers) {
    if (!["retrieval", "training"].includes(crawler.family)) {
      problems.push({
        kind: "unknown-family",
        entry: crawler.slug,
        detail: `family "${crawler.family}" is not retrieval | training`,
      });
    }
    if (typeof crawler.source !== "string" || !/^https?:\/\//.test(crawler.source)) {
      problems.push({
        kind: "unsourced",
        entry: crawler.slug,
        detail: "no operator page — a classification without a source does not ship",
      });
    }
    if (!/^\d{4}-\d{2}-\d{2}$/.test(crawler.as_of)) {
      problems.push({
        kind: "unsourced",
        entry: crawler.slug,
        detail: `as_of "${crawler.as_of}" is not an ISO date`,
      });
    } else {
      const age = ageInDays(crawler.as_of, now);
      if (age > maxAgeDays) {
        problems.push({
          kind: "stale",
          entry: crawler.slug,
          detail: `as_of ${crawler.as_of} is ${age} days old (limit ${maxAgeDays})`,
        });
      } else if (age < 0) {
        problems.push({
          kind: "future-dated",
          entry: crawler.slug,
          detail: `as_of ${crawler.as_of} is in the future — a source cannot be read before it exists`,
        });
      }
    }
    const previous = byUa.get(crawler.ua);
    if (previous !== undefined) {
      problems.push({
        kind: "duplicate-ua",
        entry: crawler.slug,
        detail: `ua "${crawler.ua}" is also declared by "${previous}"`,
      });
    }
    byUa.set(crawler.ua, crawler.slug);
  }

  for (const family of ["retrieval", "training"] as const) {
    if (!crawlers.some((crawler) => crawler.family === family)) {
      problems.push({
        kind: "empty-group",
        entry: family,
        detail: `no "${family}" crawler — a robots.txt without that group does not express the policy`,
      });
    }
  }
  return problems;
}

function groupOf(
  crawlers: readonly AiCrawler[],
  family: AiCrawlerFamily,
  now: Date,
): AiCrawlerReport[] {
  return crawlers
    .filter((crawler) => crawler.family === family)
    .map((crawler) => ({
      slug: crawler.slug,
      ua: crawler.ua,
      operator: crawler.operator,
      source: crawler.source,
      asOf: crawler.as_of,
      ageDays: ageInDays(crawler.as_of, now),
    }));
}

/**
 * `robots.txt` — two explicit groups, every UA line preceded by the registry
 * evidence that put it there (the issue's "tell WHY a UA is in which group"),
 * and never a wildcard group.
 */
export function renderRobots(
  crawlers: readonly AiCrawler[],
  asOf: string = AI_POLICY_AS_OF,
): string {
  const group = (family: AiCrawlerFamily, rule: "Allow" | "Disallow", why: string): string[] => {
    const rows = crawlers.filter((crawler) => crawler.family === family);
    const header = [`# ai-${family} — ${why} (ai-policy v${AI_POLICY_VERSION}, as of ${asOf})`];
    const agents = rows.flatMap((crawler) => [
      `#   ${crawler.slug} · ${crawler.operator} · source ${crawler.source} · as of ${crawler.as_of}`,
      `User-agent: ${crawler.ua}`,
    ]);
    return [...header, ...agents, `${rule}: /`, ""];
  };

  return [
    `# robots.txt — AI policy for this site (ai-policy v${AI_POLICY_VERSION}).`,
    `# Retrieval is ALLOWED (search and answer indexing, user-initiated fetches);`,
    `# AI training is BLOCKED by default — the owner's stated policy, quoted in`,
    `# AI-POLICY.md. Two named groups, never a wildcard: a \`User-agent: *\``,
    `# allow-all would contradict the training block.`,
    `# Generated by pasco export ai-policy — regenerate rather than edit.`,
    "",
    ...group("retrieval", "Allow", "allowed: the output is a citation"),
    ...group("training", "Disallow", "blocked: foundation-model corpus crawlers"),
  ].join("\n");
}

/** A document the generated `llms.txt` claims to index (its coverage unit). */
export interface LlmsDocument {
  /** Stable id, used in the assertion message: `identity`, `faq.<id>`, `publication.<n>`. */
  id: string;
  /** The exact line the emitted text must contain. */
  line: string;
}

/** The facts `llms.txt` is built from, already resolved to one language. */
export interface LlmsInput {
  name: string;
  definition?: string;
  identityUrl?: string;
  faq: { id: string; q: string; a: string; source?: string }[];
  publications: { title: string; venue: string; year: number; url?: string; doi?: string }[];
  policy: { version: number; asOf: string };
}

/** Resolve the workspace into the input `llms.txt` renders (`lang` already applied). */
export function llmsInput(profile: LoadedProfile, lang: Lang): LlmsInput {
  const definition = profile.identity.definition?.[lang] ?? profile.identity.definition?.en;
  const faq = (profile.faq ?? []).map((row) => ({
    id: row.id,
    q: row.q[lang] ?? row.q.en,
    a: row.a[lang] ?? row.a.en,
    ...(row.source !== undefined ? { source: row.source } : {}),
  }));
  const publications = (profile.publications ?? []).map((row) => ({
    title: row.title,
    venue: row.venue,
    year: row.year,
    ...(row.url !== undefined ? { url: row.url } : {}),
    ...(row.doi !== undefined ? { doi: row.doi } : {}),
  }));
  const identityUrl = entityId(profile.identity);
  return {
    name: profile.identity.name,
    ...(definition !== undefined ? { definition } : {}),
    ...(identityUrl !== undefined ? { identityUrl } : {}),
    faq,
    publications,
    policy: { version: AI_POLICY_VERSION, asOf: AI_POLICY_AS_OF },
  };
}

/**
 * The documents `llms.txt` must index, in emission order. The builder renders
 * FROM this list, then asserts every entry survived — a document missing from
 * the index is a silent hole, not a cosmetic bug (the `scripts/site-docs`
 * precedent).
 */
export function llmsDocuments(input: LlmsInput): LlmsDocument[] {
  const documents: LlmsDocument[] = [];
  if (input.identityUrl !== undefined) {
    documents.push({
      id: "identity",
      line: `- Canonical identity: ${input.identityUrl}`,
    });
  }
  documents.push({
    id: "ai-policy",
    line: `- [AI-POLICY.md](AI-POLICY.md): retrieval allowed, AI training blocked by default (ai-policy v${input.policy.version}, as of ${input.policy.asOf}).`,
  });
  for (const row of input.faq) {
    documents.push({ id: `faq.${row.id}`, line: `### ${row.q}` });
  }
  input.publications.forEach((row, index) => {
    const link =
      row.doi !== undefined
        ? `https://doi.org/${row.doi}`
        : row.url !== undefined
          ? row.url
          : undefined;
    documents.push({
      id: `publication.${index + 1}`,
      line: `- ${row.title} — ${row.venue}, ${row.year}${link !== undefined ? `: ${link}` : ""}`,
    });
  });
  return documents;
}

/**
 * The coverage assertion, exported so a test can prove it FAILS when a section
 * is dropped: every claimed document must appear in the emitted text.
 */
export function assertLlmsCoverage(text: string, documents: readonly LlmsDocument[]): void {
  for (const document of documents) {
    if (!text.includes(document.line)) {
      throw new Error(
        `llms.txt does not index ${document.id} — the document would be a silent hole`,
      );
    }
  }
}

/** The generated `llms.txt` (site-docs shape, workspace input). */
export function renderLlmsTxt(input: LlmsInput): string {
  const documents = llmsDocuments(input);
  const sections = new Map<string, string[]>();
  const section = (name: string): string[] => {
    const rows = sections.get(name) ?? [];
    sections.set(name, rows);
    return rows;
  };

  const head: string[] = [`# ${input.name}`, ""];
  if (input.definition !== undefined) head.push(`> ${input.definition}`, "");
  head.push(
    `<!-- ${AI_POLICY_MARKER} (ai-policy v${input.policy.version}, as of ${input.policy.asOf}) — regenerate rather than edit. -->`,
    "",
  );
  const identity = documents.find((document) => document.id === "identity");
  if (identity !== undefined) head.push(identity.line);
  head.push(documents.find((document) => document.id === "ai-policy")?.line ?? "");

  for (const document of documents) {
    if (document.id.startsWith("faq.")) {
      section("Answers").push(document.line);
      const row = input.faq.find((candidate) => `faq.${candidate.id}` === document.id);
      if (row !== undefined) {
        sections.get("Answers")?.push(row.a, "");
        if (row.source !== undefined) sections.get("Answers")?.push(`Source: ${row.source}`, "");
      }
    } else if (document.id.startsWith("publication.")) {
      section("Publications").push(document.line);
    }
  }

  const body: string[] = [];
  for (const [title, rows] of sections) {
    if (rows.length === 0) continue;
    // One blank line between the heading and its rows, one after the block —
    // the rows themselves already carry the blank line between entries.
    body.push("", `## ${title}`, "", ...rows);
    while (body.at(-1) === "") body.pop();
  }

  const text = `${[...head, ...body].join("\n").trimEnd()}\n`;
  assertLlmsCoverage(text, documents);
  return text;
}

/** The generated `AI-POLICY.md` — the statement a client can be sent. */
export function renderAiPolicy(input: LlmsInput, asOf: string = AI_POLICY_AS_OF): string {
  const crawlerTable = AI_CRAWLERS.map(
    (crawler) =>
      `| \`${crawler.slug}\` | \`${crawler.ua}\` | ${crawler.operator} | [source](${crawler.source}) | ${crawler.as_of} |`,
  );
  const family = (name: AiCrawlerFamily) =>
    crawlerTable.filter((_, index) => AI_CRAWLERS[index]?.family === name);

  return [
    `# AI policy — ${input.name}`,
    "",
    `<!-- ${AI_POLICY_MARKER} (ai-policy v${input.policy.version}, as of ${asOf}) — regenerate rather than edit. -->`,
    "",
    `**Policy version:** ${input.policy.version} · **Effective date:** ${asOf}`,
    "",
    "## The stance (SPEC §12 M9, quoted verbatim)",
    "",
    `> ${AI_POLICY_STANCE}`,
    "",
    "In plain terms: the crawlers whose output is a **citation** — search and",
    "answer indexing, and a fetch a user asked for — may read this site. The",
    "crawlers that collect material for **foundation-model training** may not.",
    "",
    "## Allowed — retrieval",
    "",
    "| Entry | User-agent | Operator | Source | As of |",
    "|---|---|---|---|---|",
    ...family("retrieval"),
    "",
    "## Blocked — training",
    "",
    "| Entry | User-agent | Operator | Source | As of |",
    "|---|---|---|---|---|",
    ...family("training"),
    "",
    "## Who can change this",
    "",
    "The profile owner. The list is generated from the ai-policy registry that",
    "ships with `pasco` — never typed into this file — and every entry carries the",
    "operator's own documentation URL and the date it was read. Regenerate with",
    "`pasco export ai-policy --out <dir>`; `pasco export ai-policy --check` fails",
    "when an entry is unsourced or older than 180 days, so this file cannot rot",
    "silently.",
    "",
    "## Date",
    "",
    `As of ${asOf}. The stamp is the registry's review date, not a generation`,
    "timestamp: two runs on different days produce byte-identical files.",
    "",
  ].join("\n");
}

/** What a write attempt produced, beyond the report. */
interface WriteOutcome {
  files: { name: string; path: string; bytes: number }[];
  error?: never;
}

/** The generated content for each artifact, from one resolved input. */
export function aiPolicyArtifacts(input: LlmsInput): Record<AiPolicyFile, string> {
  return {
    "robots.txt": renderRobots(AI_CRAWLERS),
    "llms.txt": renderLlmsTxt(input),
    "AI-POLICY.md": renderAiPolicy(input),
  };
}

/**
 * Write the three artifacts. Every target is validated BEFORE any is written, and
 * each write is a temp file + rename (atomic per file). A file that does not
 * carry `AI_POLICY_MARKER` is the user's, not ours: it is refused unless
 * `--force`.
 */
function writeArtifacts(dir: string, artifacts: Record<AiPolicyFile, string>, force: boolean) {
  const targets = AI_POLICY_FILES.map((name) => ({ name, path: join(dir, name) }));
  for (const target of targets) {
    if (!force && existsSync(target.path)) {
      const current = readFileSync(target.path, "utf8");
      if (!current.includes(AI_POLICY_MARKER)) {
        return {
          error: `refusing to overwrite "${target.path}" — it was not generated by pasco (pass --force to replace it)`,
        } as const;
      }
    }
  }
  try {
    mkdirSync(dir, { recursive: true });
  } catch (err) {
    return { error: `cannot create "${dir}": ${(err as Error).message}` } as const;
  }
  const files: WriteOutcome["files"] = [];
  for (const target of targets) {
    const content = artifacts[target.name];
    const temp = `${target.path}.${process.pid}.pasco-tmp`;
    try {
      writeFileSync(temp, content, "utf8");
      renameSync(temp, target.path);
    } catch (err) {
      try {
        unlinkSync(temp);
      } catch {
        // The temp file may not exist — nothing to clean up.
      }
      return { error: `cannot write "${target.path}": ${(err as Error).message}` } as const;
    }
    files.push({ name: target.name, path: target.path, bytes: Buffer.byteLength(content) });
  }
  return { files };
}

/** `--check`: the UA list only. No workspace, no profile — this is registry data. */
export function checkAiPolicy(now: Date): AiPolicyData {
  const problems = checkCrawlers(AI_CRAWLERS, now);
  return {
    schemaVersion: AI_POLICY_SCHEMA_VERSION,
    policy: {
      version: AI_POLICY_VERSION,
      asOf: AI_POLICY_AS_OF,
      stance: AI_POLICY_STANCE,
      maxAgeDays: AI_POLICY_MAX_AGE_DAYS,
    },
    groups: {
      retrieval: groupOf(AI_CRAWLERS, "retrieval", now),
      training: groupOf(AI_CRAWLERS, "training", now),
    },
    problems,
  };
}

/** Human output shared by both modes: the policy line, the groups, the problems. */
function printReport(data: AiPolicyData): void {
  section(
    `ai-policy v${data.policy.version} — as of ${data.policy.asOf} · ` +
      `${data.groups.retrieval.length} retrieval (allowed) + ${data.groups.training.length} training (blocked)`,
  );
  for (const [family, rows] of Object.entries(data.groups)) {
    const rule = family === "retrieval" ? "allow" : "disallow";
    line(`  ${family} (${rule}): ${rows.map((row) => row.ua).join(", ") || "(none)"}`);
  }
  for (const problem of data.problems) {
    line(`  ${problem.kind} · ${problem.entry} — ${problem.detail}`);
  }
}

export interface AiPolicyCheckArgs {
  /** Injected clock: the 180-day window is the one dated rule (SPEC §7.3). */
  now: Date;
}

export function runAiPolicyCheck(args: AiPolicyCheckArgs): number {
  const data = checkAiPolicy(args.now);
  const ok = data.problems.length === 0;
  const exitCode = ok ? EXIT.OK : EXIT.FAIL;

  if (isJsonMode()) {
    return report("export ai-policy", ok, exitCode, { data });
  }
  printReport(data);
  line(
    ok
      ? `pasco export ai-policy --check: ${AI_CRAWLERS.length} crawler(s) sourced and inside the ${AI_POLICY_MAX_AGE_DAYS}-day window — exit 0`
      : `pasco export ai-policy --check: ${data.problems.length} problem(s) — the UA list must be sourced and reviewed before it ships — exit 1`,
  );
  return exitCode;
}

export interface AiPolicyExportArgs {
  workspace: string;
  /** Destination directory (created if missing). */
  out: string;
  /** Replace files that pasco did not generate. */
  force: boolean;
  /** Resolved language for the workspace text in `llms.txt` (dispatcher applies the default). */
  lang: Lang;
  pascorc: Pascorc;
  /** Injected clock for the pre-write `--check` (the artifacts themselves use no clock). */
  now: Date;
}

export function runAiPolicyExport(args: AiPolicyExportArgs): number {
  // The generator refuses to write what `--check` would reject: rot becomes a
  // failing command instead of a committed file nobody re-reads.
  const checked = checkAiPolicy(args.now);
  if (checked.problems.length > 0) {
    if (isJsonMode()) {
      return report("export ai-policy", false, EXIT.FAIL, { data: checked });
    }
    printReport(checked);
    line(
      `pasco export ai-policy: refusing to write an unsourced or stale UA list — ${checked.problems.length} problem(s) — exit 1`,
    );
    return EXIT.FAIL;
  }

  let profile: LoadedProfile;
  try {
    profile = load(args.workspace);
  } catch (err) {
    if (err instanceof SchemaValidationError) {
      return report("export ai-policy", false, EXIT.FAIL, {
        error: {
          kind: "schema",
          message: `schema validation failed (D12 fail-on-schema) — ${err.issues.length} violation(s)`,
          violations: [...err.issues],
        },
      });
    }
    if (err instanceof LoadError) {
      return report("export ai-policy", false, EXIT.FAIL, {
        error: { kind: "load", message: err.message },
      });
    }
    throw err;
  }

  const input = llmsInput(profile, args.lang);
  const written = writeArtifacts(resolve(args.out), aiPolicyArtifacts(input), args.force);
  if (written.error !== undefined) {
    return report("export ai-policy", false, EXIT.FAIL, {
      error: { kind: "write", message: written.error },
    });
  }

  const data: AiPolicyData = { ...checked, files: written.files };
  if (isJsonMode()) {
    return report("export ai-policy", true, EXIT.OK, { data });
  }
  printReport(data);
  if (input.identityUrl === undefined) {
    line(
      "  warning: no role: identity link — llms.txt omits the canonical URL (the engine never invents one, §7.2)",
    );
  }
  line(`  ${input.faq.length} faq row(s) · ${input.publications.length} publication(s) indexed`);
  for (const file of written.files) {
    line(`  wrote ${file.path} (${file.bytes} bytes)`);
  }
  line(`pasco export ai-policy: ${written.files.length} file(s) written — exit 0`);
  return EXIT.OK;
}
